const $=s=>document.querySelector(s);let riderId=localStorage.getItem('ttb-driver')||localStorage.getItem('swiftbite-rider')||'rider-001';let current=null;let watcher=null;let watcherType='web';
function toast(m){const t=$('#toast');t.textContent=m;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2200)}
async function api(path,options={}){const r=await fetch(path,{headers:{'Content-Type':'application/json'},...options});const d=await r.json();if(!r.ok)throw new Error(d.error||'Request failed');return d}
function statusRank(s){return ['Assigned','Accepted','At kitchen','Picked up','Out for delivery','Arrived','Delivered'].indexOf(s)}
function render(r){current=r;const online=r.availability!=='offline';$('#availabilityText').textContent=r.availability[0].toUpperCase()+r.availability.slice(1);$('#availabilityToggle').classList.toggle('on',online);$('#riderStatus').classList.toggle('online',online);$('#riderStatus span').textContent=online?'Online':'Offline';$('#jobCard').hidden=!r.current_order;$('#emptyJob').hidden=!!r.current_order;if(r.latitude!=null){$('#gpsLabel').textContent='Driver location active';$('#gpsData').textContent=`${Number(r.latitude).toFixed(5)}, ${Number(r.longitude).toFixed(5)} · ${r.last_location_at?'updated '+new Date(r.last_location_at).toLocaleTimeString():'seed location'}`;TTB.renderMap('riderMap',[{lat:Number(r.latitude),lng:Number(r.longitude),label:'D',title:r.name},{lat:-37.8007,lng:144.9658,label:'C',title:'Customer'}])}
 if(r.current_order){const o=r.current_order,a=o.assignment;$('#jobId').textContent=o.id;$('#jobCustomer').textContent=o.customer_name;$('#jobStatus').textContent=o.status;$('#jobEta').textContent=`${o.eta_minutes} min ETA`;$('#jobTotal').textContent=`₹${o.total}`;$('#jobAddress').textContent=o.address;const rank=statusRank(a?.status||o.status);document.querySelectorAll('[data-step]').forEach(b=>{if(b.dataset.step==='accept')b.disabled=rank>=1;else b.disabled=statusRank(b.dataset.step)!==rank+1});}}
async function loadRiders(){const d=await api('/api/v1/riders');$('#riderSelect').innerHTML=d.riders.map(r=>`<option value="${r.id}">${r.name} · ${r.vehicle}</option>`).join('');$('#riderSelect').value=riderId;await refresh()}
async function refresh(){try{render(await api(`/api/v1/riders/${riderId}`))}catch(e){toast(e.message)}}
$('#riderSelect').onchange=e=>{riderId=e.target.value;localStorage.setItem('ttb-driver',riderId);refresh()};
$('#availabilityToggle').onclick=async()=>{try{render(await api(`/api/v1/riders/${riderId}/availability`,{method:'POST',body:JSON.stringify({availability:current.availability==='offline'?'online':'offline'})}));toast(`You are ${current.availability}`)}catch(e){toast(e.message)}};
async function sendLocation(lat,lng){try{render(await api(`/api/v1/riders/${riderId}/location`,{method:'POST',body:JSON.stringify({latitude:lat,longitude:lng})}));toast('Location updated')}catch(e){toast(e.message)}}
$('#demoLocation').onclick=()=>sendLocation(-37.8007+Math.random()*.002,144.9658+Math.random()*.002);
$('#shareLocation').onclick=async()=>{const nativeGeo=window.TTBNative?.Geolocation;if(watcher!==null){if(watcherType==='native'&&nativeGeo)await nativeGeo.clearWatch({id:watcher});else navigator.geolocation?.clearWatch(watcher);watcher=null;$('#shareLocation').textContent='Share live location';return toast('Live sharing paused')}try{if(nativeGeo&&window.TTBNative?.isNative){const permission=await nativeGeo.requestPermissions({permissions:['location']});if(permission.location!=='granted')throw new Error('Precise location permission is required');watcherType='native';watcher=await nativeGeo.watchPosition({enableHighAccuracy:true,maximumAge:10000,timeout:15000},(p,e)=>{if(e)return toast(e.message||'Location update failed');if(p)sendLocation(p.coords.latitude,p.coords.longitude)})}else{if(!navigator.geolocation)throw new Error('Geolocation is unavailable');watcherType='web';watcher=navigator.geolocation.watchPosition(p=>sendLocation(p.coords.latitude,p.coords.longitude),e=>toast(e.message),{enableHighAccuracy:true,maximumAge:10000,timeout:15000})}$('#shareLocation').textContent='Pause live location';toast('Live location sharing started')}catch(error){toast(error.message||'Location permission was not granted')}};
document.addEventListener('click',async e=>{const b=e.target.closest('[data-step]');if(!b||!current?.current_order)return;try{const id=current.current_order.id;if(b.dataset.step==='accept')await api(`/api/v1/orders/${id}/accept`,{method:'POST',body:JSON.stringify({rider_id:riderId})});else await api(`/api/v1/orders/${id}/status`,{method:'POST',body:JSON.stringify({rider_id:riderId,status:b.dataset.step})});toast(b.dataset.step==='accept'?'Delivery accepted':`Status: ${b.dataset.step}`);await refresh()}catch(err){toast(err.message)}});
loadRiders();setInterval(refresh,5000);
